sections.css:
.hero-section{min-height: 100vh; display: flex; flex-direction: column; justify-content: center; padding-top: 7rem; padding-bottom: 4rem;}
.hero-eyebrow{display: flex; align-items: center; gap: 1rem; margin-bottom: 2.2rem; opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.2s 1 normal forwards running reveal-up;}
.eyebrow-line{width: 2.5rem; height: 1px; background: linear-gradient(90deg, var(--amber), transparent);}
.eyebrow-text{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; font-weight: 400; letter-spacing: 0.28em; text-transform: uppercase; color: var(--amber-dim);}
.hero-title{font-family: "Playfair Display", serif; font-size: clamp(3.2rem, 5.5vw, 5.8rem); font-weight: 400; line-height: 0.95; letter-spacing: -0.02em; margin-bottom: 1.2rem; opacity: 0; animation: 1s cubic-bezier(0.16, 1, 0.3, 1) 0.35s 1 normal forwards running reveal-up;}
.hero-title em{font-style: italic; color: var(--amber); font-weight: 300;}
.hero-title .line-thin{font-weight: 300; color: var(--text-secondary); font-size: 0.65em; display: block; letter-spacing: 0.04em; font-family: "Inter Tight", sans-serif; font-style: normal; margin-top: 0.4em;}
.hero-sub{font-size: 0.88rem; line-height: 1.8; color: var(--text-secondary); font-weight: 300; max-width: 46ch; margin-bottom: 3rem; opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.5s 1 normal forwards running reveal-up;}
.hero-actions{display: flex; gap: 1rem; align-items: center; margin-bottom: 5rem; opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.65s 1 normal forwards running reveal-up;}
.btn-primary{position: relative; padding: 0.9rem 2.4rem; font-family: "JetBrains Mono", monospace; font-size: 0.68rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; color: var(--void); background: linear-gradient(135deg, var(--amber), oklch(65% 0.16 75)); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 3px; cursor: none; overflow: hidden; transition: box-shadow 0.35s, transform 0.2s;}
.btn-primary::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--bx,50%) var(--by,50%), oklch(100% 0 0 / 0.3) 0%, transparent 65%); opacity: 0; transition: opacity 0.3s;}
.btn-primary:hover{box-shadow: 0 0 40px 8px var(--amber-glow), 0 8px 32px oklch(0% 0 0 / 0.4); transform: translateY(-1px);}
.btn-primary:hover::before{opacity: 1;}
.btn-secondary{position: relative; padding: 0.9rem 2rem; font-family: "JetBrains Mono", monospace; font-size: 0.68rem; font-weight: 400; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-secondary); background: var(--glass-fill); border: 1px solid var(--glass-border); border-radius: 3px; cursor: none; transition: color 0.3s, border-color 0.3s, background 0.3s;}
.btn-secondary:hover{color: var(--text-primary); border-color: var(--glass-border-bright); background: oklch(1 0 0 / 0.05);}
.hero-stat-row{display: flex; gap: 3rem; padding-top: 2.5rem; border-top: 1px solid var(--glass-border); opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.8s 1 normal forwards running reveal-up;}
.stat-item{}
.stat-value{font-family: "Playfair Display", serif; font-size: 2.4rem; font-weight: 400; letter-spacing: -0.03em; color: var(--text-primary); line-height: 1;}
.stat-value span{font-family: "Inter Tight", sans-serif; font-size: 1rem; font-weight: 300; color: var(--amber);}
.stat-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--text-tertiary); margin-top: 0.4rem;}

.anodized-section{padding: 8rem 0px;}
.section-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; font-weight: 400; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 1.8rem; display: flex; align-items: center; gap: 0.8rem;}
.section-label::before{content: ""; display: block; width: 1.5rem; height: 1px; background: var(--amber-dim);}
.section-title{font-family: "Playfair Display", serif; font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 400; letter-spacing: -0.02em; line-height: 1.05; margin-bottom: 1rem;}
.section-title em{font-style: italic; color: var(--amber);}
.anodized-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--glass-border); border: 1px solid var(--glass-border); border-radius: 6px; overflow: hidden; margin-top: 3.5rem;}
.anodized-cell{position: relative; background: var(--titanium-base); padding: 2.2rem; overflow: hidden; transition: background 0.4s;}
.anodized-cell::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse at var(--cx,50%) var(--cy,50%), oklch(72% 0.18 85 / 0.06) 0%, transparent 60%); opacity: 0; transition: opacity 0.4s;}
.anodized-cell:hover{background: var(--titanium-mid);}
.anodized-cell:hover::before{opacity: 1;}
.anodized-cell.accent{background: oklch(0.16 0.025 85);}
.cell-icon{width: 36px; height: 36px; border-radius: 6px; background: oklch(1 0 0 / 0.04); border: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: center; margin-bottom: 1.4rem; font-size: 0.85rem;}
.cell-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 0.7rem;}
.cell-title{font-size: 1.05rem; font-weight: 500; letter-spacing: -0.02em; margin-bottom: 0.7rem; line-height: 1.2;}
.cell-body{font-size: 0.78rem; line-height: 1.75; color: var(--text-secondary); font-weight: 300;}
.cell-metric{font-family: "Playfair Display", serif; font-size: 2.8rem; font-weight: 400; letter-spacing: -0.03em; color: var(--text-primary); line-height: 1; margin-bottom: 0.3rem;}
.cell-metric-unit{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--text-tertiary);}
.inner-shadow-card{box-shadow: oklch(1 0 0 / 0.06) 0px 1px 0px inset, oklch(0 0 0 / 0.3) 0px -1px 0px inset, oklch(1 0 0 / 0.04) 1px 0px 0px inset, oklch(0 0 0 / 0.2) -1px 0px 0px inset, oklch(0 0 0 / 0.4) 0px 4px 24px;}
.telemetry-bar{display: flex; flex-direction: column; gap: 0.5rem; margin-top: 1.2rem;}
.telem-row{display: flex; align-items: center; gap: 0.8rem; font-family: "JetBrains Mono", monospace;}
.telem-key{font-size: 0.58rem; color: var(--text-tertiary); letter-spacing: 0.1em; text-transform: uppercase; flex: 0 0 80px;}
.telem-track{flex: 1 1 0%; height: 3px; background: oklch(1 0 0 / 0.06); border-radius: 2px; overflow: hidden;}
.telem-fill{height: 100%; border-radius: 2px; background: linear-gradient(90deg, var(--cyan), var(--amber)); position: relative;}
.telem-fill::after{content: ""; position: absolute; inset: 0px; background: linear-gradient(90deg, transparent, oklch(1 0 0 / 0.4), transparent); animation: 2.5s ease-in-out 0s infinite normal none running shimmer-t;}
.telem-val{font-size: 0.6rem; color: var(--amber); flex: 0 0 40px; text-align: right;}
.ledger-live{display: flex; align-items: center; gap: 0.5rem; font-family: "JetBrains Mono", monospace; font-size: 0.55rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--amber);}
.pulse-dot{width: 5px; height: 5px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 8px 2px var(--amber-glow); animation: 2s ease-in-out 0s infinite normal none running pulse-a;}

.section-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; font-weight: 400; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 1.8rem; display: flex; align-items: center; gap: 0.8rem;}
.section-label::before{content: ""; display: block; width: 1.5rem; height: 1px; background: var(--amber-dim);}
.section-title{font-family: "Playfair Display", serif; font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 400; letter-spacing: -0.02em; line-height: 1.05; margin-bottom: 1rem;}
.section-title em{font-style: italic; color: var(--amber);}
.assembly-section{padding: 8rem 0px;}
.circuit-row{display: flex; flex-direction: column; gap: 1px; background: var(--glass-border); border: 1px solid var(--glass-border); border-radius: 6px; overflow: hidden; margin-top: 3.5rem;}
.circuit-item{display: flex; align-items: center; gap: 2rem; padding: 1.6rem 2rem; background: var(--titanium-base); position: relative; overflow: hidden; opacity: 0; transform: translateX(-20px); transition: background 0.3s, opacity 0.6s, transform 0.6s;}
.circuit-item.assembled{opacity: 1; transform: translateX(0px);}
.circuit-item::after{content: ""; position: absolute; left: 0px; top: 0px; bottom: 0px; width: 2px; background: linear-gradient(180deg, var(--amber), var(--cyan)); box-shadow: 0 0 10px 2px var(--amber-glow); transform: scaleY(0); transform-origin: center top; transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);}
.circuit-item.assembled::after{transform: scaleY(1);}
.circuit-num{font-family: "Playfair Display", serif; font-size: 2rem; font-weight: 400; color: oklch(1 0 0 / 0.08); flex: 0 0 3rem; line-height: 1;}
.circuit-content{flex: 1 1 0%;}
.circuit-title{font-size: 0.9rem; font-weight: 500; letter-spacing: -0.01em; margin-bottom: 0.3rem;}
.circuit-desc{font-size: 0.75rem; color: var(--text-secondary); line-height: 1.6; font-weight: 300;}
.circuit-badge{font-family: "JetBrains Mono", monospace; font-size: 0.55rem; letter-spacing: 0.12em; text-transform: uppercase; padding: 0.3rem 0.8rem; border-radius: 100px; border: 1px solid var(--glass-border); color: var(--text-tertiary); white-space: nowrap; flex-shrink: 0;}
.circuit-badge.active{color: var(--amber); border-color: oklch(0.72 0.18 85 / 0.3); background: oklch(0.72 0.18 85 / 0.07); box-shadow: 0 0 12px var(--amber-glow);}

.section-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; font-weight: 400; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 1.8rem; display: flex; align-items: center; gap: 0.8rem;}
.section-label::before{content: ""; display: block; width: 1.5rem; height: 1px; background: var(--amber-dim);}
.section-title{font-family: "Playfair Display", serif; font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 400; letter-spacing: -0.02em; line-height: 1.05; margin-bottom: 1rem;}
.section-title em{font-style: italic; color: var(--amber);}
.inner-shadow-card{box-shadow: oklch(1 0 0 / 0.06) 0px 1px 0px inset, oklch(0 0 0 / 0.3) 0px -1px 0px inset, oklch(1 0 0 / 0.04) 1px 0px 0px inset, oklch(0 0 0 / 0.2) -1px 0px 0px inset, oklch(0 0 0 / 0.4) 0px 4px 24px;}
.ledger-section{padding: 8rem 0px;}
.ledger-display{background: var(--titanium-base); border: 1px solid var(--glass-border); border-radius: 6px; overflow: hidden; margin-top: 3.5rem;}
.ledger-header{padding: 1.2rem 2rem; background: oklch(1 0 0 / 0.02); border-bottom: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: space-between;}
.ledger-title-bar{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-tertiary);}
.ledger-live{display: flex; align-items: center; gap: 0.5rem; font-family: "JetBrains Mono", monospace; font-size: 0.55rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--amber);}
.pulse-dot{width: 5px; height: 5px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 8px 2px var(--amber-glow); animation: 2s ease-in-out 0s infinite normal none running pulse-a;}
.ledger-entries{display: flex; flex-direction: column;}
.ledger-entry{display: flex; align-items: center; padding: 1.1rem 2rem; border-bottom: 1px solid var(--glass-border); gap: 1.5rem; position: relative; overflow: hidden; transition: background 0.3s;}
.ledger-entry:last-child{border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}
.ledger-entry:hover{background: oklch(1 0 0 / 0.02);}
.entry-icon{width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; flex-shrink: 0; border: 1px solid var(--glass-border); background: oklch(1 0 0 / 0.04);}
.entry-merchant{font-size: 0.82rem; font-weight: 500;}
.entry-category{font-family: "JetBrains Mono", monospace; font-size: 0.55rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-tertiary); margin-top: 0.2rem;}
.entry-amount{margin-left: auto; font-family: "Playfair Display", serif; font-size: 1.05rem; font-weight: 400; letter-spacing: -0.01em;}
.entry-amount.debit{color: var(--text-primary);}
.entry-amount.credit{color: var(--amber);}
.entry-time{font-family: "JetBrains Mono", monospace; font-size: 0.55rem; color: var(--text-tertiary); letter-spacing: 0.08em; flex-shrink: 0;}
.entry-stream{position: absolute; left: 0px; top: 0px; bottom: 0px; width: 1px; background: linear-gradient(180deg, transparent, var(--amber-dim), transparent); opacity: 0; transition: opacity 0.3s;}
.ledger-entry:hover .entry-stream{opacity: 0.6;}
.chart-area{padding: 1.5rem 2rem; border-top: 1px solid var(--glass-border);}
.chart-label{font-family: "JetBrains Mono", monospace; font-size: 0.55rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--text-tertiary); margin-bottom: 1rem;}
.sparkline-container{position: relative; height: 60px;}
.sparkline-container svg{width: 100%; height: 100%;}

.section-label{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; font-weight: 400; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 1.8rem; display: flex; align-items: center; gap: 0.8rem;}
.section-label::before{content: ""; display: block; width: 1.5rem; height: 1px; background: var(--amber-dim);}
.section-title{font-family: "Playfair Display", serif; font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 400; letter-spacing: -0.02em; line-height: 1.05; margin-bottom: 1rem;}
.section-title em{font-style: italic; color: var(--amber);}
.inner-shadow-card{box-shadow: oklch(1 0 0 / 0.06) 0px 1px 0px inset, oklch(0 0 0 / 0.3) 0px -1px 0px inset, oklch(1 0 0 / 0.04) 1px 0px 0px inset, oklch(0 0 0 / 0.2) -1px 0px 0px inset, oklch(0 0 0 / 0.4) 0px 4px 24px;}
.secure-section{padding: 8rem 0px 12rem;}
.secure-grid{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1px; background: var(--glass-border); border: 1px solid var(--glass-border); border-radius: 6px; overflow: hidden; margin-top: 3.5rem;}
.secure-cell{padding: 2rem 1.8rem; background: var(--titanium-base); position: relative; overflow: hidden; transition: background 0.4s;}
.secure-cell::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse at var(--cx,50%) var(--cy,50%), oklch(68% 0.16 220 / 0.07) 0%, transparent 60%); opacity: 0; transition: opacity 0.4s;}
.secure-cell:hover{background: var(--titanium-mid);}
.secure-cell:hover::before{opacity: 1;}
.secure-icon{font-size: 1.4rem; margin-bottom: 1.2rem; display: block;}
.secure-title{font-size: 0.9rem; font-weight: 500; margin-bottom: 0.6rem; letter-spacing: -0.01em;}
.secure-desc{font-size: 0.73rem; line-height: 1.7; color: var(--text-secondary); font-weight: 300;}
.secure-stat{font-family: "JetBrains Mono", monospace; font-size: 0.58rem; color: var(--cyan-dim); margin-top: 1rem; letter-spacing: 0.08em;}
